"use client";

import type { Meta, StoryObj } from "@storybook/react-vite";

import { BlockStory } from "../../shared/block-story";
import { useState } from "react";
import Button from "@mui/material/Button";
import Checkbox from "@mui/material/Checkbox";
import List from "@mui/material/List";
import ListItemButton from "@mui/material/ListItemButton";
import ListItemIcon from "@mui/material/ListItemIcon";
import ListItemText from "@mui/material/ListItemText";
import Stack from "@mui/material/Stack";

const meta = {
  title: "MUI/Components/TransferList",
  tags: ["autodocs"],
  parameters: {
    docs: {
      description: {
        component: `Move items between two lists.`,
      },
    },
  },
} satisfies Meta;

export default meta;
type Story = StoryObj<typeof meta>;

export const Basic: Story = {
  name: "Basic",
  render: () => {
    function not(a: readonly number[], b: readonly number[]) {
      return a.filter((v) => !b.includes(v));
    }
    function intersection(a: readonly number[], b: readonly number[]) {
      return a.filter((v) => b.includes(v));
    }
    function TransferListDemo() {
      const [left, setLeft] = useState([0, 1, 2]);
      const [right, setRight] = useState<number[]>([3]);
      const [checked, setChecked] = useState<readonly number[]>([]);
      const leftChecked = intersection(checked, left);
      const rightChecked = intersection(checked, right);
      const handleToggle = (value: number) => () => {
        const i = checked.indexOf(value);
        setChecked(i === -1 ? [...checked, value] : checked.filter((v) => v !== value));
      };
      const customList = (items: readonly number[]) => (
        <List
          dense
          sx={{
            width: 140,
            bgcolor: "background.paper",
            border: 1,
            borderColor: "divider",
            borderRadius: 1,
          }}
        >
          {items.map((value) => (
            <ListItemButton key={value} onClick={handleToggle(value)}>
              <ListItemIcon>
                <Checkbox
                  edge="start"
                  checked={checked.includes(value)}
                  tabIndex={-1}
                  disableRipple
                />
              </ListItemIcon>
              <ListItemText primary={`Item ${value + 1}`} />
            </ListItemButton>
          ))}
        </List>
      );
      return (
        <Stack direction="row" spacing={1} sx={{ alignItems: "center" }}>
          {customList(left)}
          <Stack spacing={1}>
            <Button
              size="small"
              variant="outlined"
              onClick={() => {
                setRight(right.concat(leftChecked));
                setLeft(not(left, leftChecked));
                setChecked(not(checked, leftChecked));
              }}
              disabled={leftChecked.length === 0}
            >
              &gt;
            </Button>
            <Button
              size="small"
              variant="outlined"
              onClick={() => {
                setLeft(left.concat(rightChecked));
                setRight(not(right, rightChecked));
                setChecked(not(checked, rightChecked));
              }}
              disabled={rightChecked.length === 0}
            >
              &lt;
            </Button>
          </Stack>
          {customList(right)}
        </Stack>
      );
    }
    return (
      <BlockStory>
        <TransferListDemo />
      </BlockStory>
    );
  },
};
